//! The stylesheet and SDK script of auth's pages, embedded under paths naming their
//! content, so browsers and shared caches keep them forever.

use crate::{
    StartupError,
    security::{ApiError, CacheClass, Cached},
};
use axum::{
    http::header,
    response::{IntoResponse, Response},
};

// Generated by `build.rs`: `Asset::STYLESHEET` and `Asset::SCRIPT`.
include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// Failures of embedded browser asset lookup.
#[derive(Debug, thiserror::Error)]
enum AssetError {
    /// No embedded file is at the requested path.
    #[error("embedded asset not found")]
    NotFound,
}
impl From<AssetError> for ApiError {
    /// Keeps missing-file replies in the same JSON shape as other browser errors.
    fn from(error: AssetError) -> Self {
        match error {
            AssetError::NotFound => Self::not_found("Not found."),
        }
    }
}

/// One embedded file, as `build.rs` named it.
struct Asset {
    /// Where it is served: `/assets/{stem}.{hash}.{extension}`.
    path: &'static str,
    /// The file's bytes, from the SDK's sources or build.
    bytes: &'static [u8],
    /// `Content-Type`, chosen by `build.rs`.
    content_type: &'static str,
}

/// The files of auth's pages, embedded in this executable.
pub(crate) struct EmbeddedAssets;
impl EmbeddedAssets {
    /// Path of the stylesheet of auth's pages.
    pub(crate) const STYLESHEET: &str = Asset::STYLESHEET.path;
    /// Path of the SDK's script, or `None` when the SDK was not built.
    pub(crate) const SCRIPT: Option<&str> = match Asset::SCRIPT {
        Some(script) => Some(script.path),
        None => None,
    };

    /// Rejects executables compiled before the SDK's script was built. Tests accept
    /// them: they build routers but never request the script.
    pub(crate) fn check() -> Result<(), StartupError> {
        if Self::SCRIPT.is_none() && !cfg!(test) {
            Err(StartupError::MissingScript)
        } else {
            Ok(())
        }
    }

    /// Serves the embedded file at exactly `path`. A file's path changes with its
    /// content, so nothing needs revalidating.
    pub(crate) fn serve(path: &str) -> Result<Response, ApiError> {
        let asset = [Some(Asset::STYLESHEET), Asset::SCRIPT]
            .into_iter()
            .flatten()
            .find(|asset| asset.path == path)
            .ok_or(AssetError::NotFound)?;
        let headers = [(header::CONTENT_TYPE, asset.content_type)];
        Ok(Cached(CacheClass::Immutable, (headers, asset.bytes)).into_response())
    }
}

#[cfg(test)]
mod tests {
    //! Focused coverage of embedded file serving.
    use super::*;

    /// The pages' stylesheet is served at the path naming its content, so it is
    /// cached forever.
    #[test]
    fn the_stylesheet_is_immutable() {
        let response = EmbeddedAssets::serve(EmbeddedAssets::STYLESHEET).expect("found");
        assert_eq!(
            response.headers()[header::CONTENT_TYPE],
            "text/css; charset=utf-8"
        );
        assert_eq!(
            response.extensions().get::<CacheClass>(),
            Some(&CacheClass::Immutable)
        );
    }
}
